question:
다음 C 코드의 연산자 우선순위에 따른 결과는?

#include <stdio.h>
int main() {
    int result = 2 + 3 * 4;
    printf("%d", result);
    return 0;
}

다음 C 코드의 실행 결과는?

#include <stdio.h>
int main() {
    int a = 10, b = 3;
    printf("%d", a / b + a % b);
    return 0;
}

다음 C 코드의 출력 결과는? (전위/후위 증감연산자)

#include <stdio.h>
int main() {
    int a = 5;
    int b = a++ + 2;
    printf("%d %d", a, b);
    return 0;
}

다음 C 코드의 출력 결과는?

#include <stdio.h>
int main() {
    int a = 5;
    int b = ++a + 2;
    printf("%d %d", a, b);
    return 0;
}

다음 C 코드의 비트 연산 결과는?

#include <stdio.h>
int main() {
    int a = 6, b = 3;
    printf("%d", a & b);
    return 0;
}

다음 C 코드의 비트 OR 연산 결과는?

#include <stdio.h>
int main() {
    int a = 6, b = 3;
    printf("%d", a | b);
    return 0;
}

다음 C 코드의 XOR 연산 결과는?

#include <stdio.h>
int main() {
    int a = 6, b = 3;
    printf("%d", a ^ b);
    return 0;
}

다음 C 코드의 시프트 연산 결과는?

#include <stdio.h>
int main() {
    int a = 3;
    printf("%d", a << 2);
    return 0;
}

다음 C 코드의 실행 결과는? (삼항 연산자)

#include <stdio.h>
int main() {
    int a = 7;
    int b = (a % 2 == 0) ? 100 : 200;
    printf("%d", b);
    return 0;
}

다음 C 코드에서 switch문의 fall-through로 인한 출력 결과는?

#include <stdio.h>
int main() {
    int a = 2;
    switch (a) {
        case 1: printf("A");
        case 2: printf("B");
        case 3: printf("C"); break;
        default: printf("D");
    }
    return 0;
}

다음 C 코드의 for문 실행 횟수(출력되는 숫자 개수)는?

#include <stdio.h>
int main() {
    int i;
    for (i = 0; i < 5; i++) {
        printf("%d ", i);
    }
    return 0;
}

다음 C 코드의 while문 실행 결과(출력되는 숫자 개수)는?

#include <stdio.h>
int main() {
    int i = 1;
    while (i <= 10) {
        i += 2;
    }
    printf("%d", i);
    return 0;
}

다음 C 코드에서 continue문으로 인한 출력 결과는?

#include <stdio.h>
int main() {
    int i;
    for (i = 1; i <= 5; i++) {
        if (i % 2 == 0) continue;
        printf("%d ", i);
    }
    return 0;
}

다음 C 코드에서 break문으로 인한 출력 결과는?

#include <stdio.h>
int main() {
    int i;
    for (i = 1; i <= 10; i++) {
        if (i == 4) break;
        printf("%d ", i);
    }
    return 0;
}

다음 C 코드의 실행 결과는? (중첩 반복문 실행 횟수)

#include <stdio.h>
int main() {
    int i, j, count = 0;
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 4; j++) {
            count++;
        }
    }
    printf("%d", count);
    return 0;
}

다음 C 코드의 strlen 함수 실행 결과는?

#include <stdio.h>
#include <string.h>
int main() {
    char str[] = "Hello";
    printf("%d", strlen(str));
    return 0;
}

다음 C 코드의 strcmp 함수 결과 해석으로 옳은 것은?

#include <stdio.h>
#include <string.h>
int main() {
    int result = strcmp("apple", "apple");
    printf("%d", result);
    return 0;
}

다음 C 코드의 strcpy와 strcat 사용 결과는?

#include <stdio.h>
#include <string.h>
int main() {
    char dest[20];
    strcpy(dest, "NH");
    strcat(dest, "Bank");
    printf("%s", dest);
    return 0;
}

다음 C 코드에서 2차원 배열 접근 결과는?

#include <stdio.h>
int main() {
    int arr[2][3] = {{1,2,3},{4,5,6}};
    printf("%d", arr[1][2]);
    return 0;
}

다음 C 코드에서 배열과 포인터의 관계에 대한 출력 결과는?

#include <stdio.h>
int main() {
    int a[5] = {10, 20, 30, 40, 50};
    printf("%d", *(a + 2));
    return 0;
}

다음 C 코드의 포인터 연산 결과는?

#include <stdio.h>
int main() {
    int a[5] = {1,2,3,4,5};
    int *p = a;
    p = p + 3;
    printf("%d", *p);
    return 0;
}

다음 C 코드에서 이중 포인터 사용 결과는?

#include <stdio.h>
int main() {
    int a = 100;
    int *p = &a;
    int **pp = &p;
    printf("%d", **pp);
    return 0;
}

다음 C 코드에서 함수 포인터 사용 결과는?

#include <stdio.h>
int add(int a, int b) { return a + b; }
int main() {
    int (*fp)(int, int) = add;
    printf("%d", fp(3, 4));
    return 0;
}

다음 C 코드는 call by value의 특성을 보여준다. 실행 결과는?

#include <stdio.h>
void change(int x) { x = 100; }
int main() {
    int a = 10;
    change(a);
    printf("%d", a);
    return 0;
}

다음 C 코드는 포인터를 이용한 call by reference 방식이다. 실행 결과는?

#include <stdio.h>
void change(int *x) { *x = 100; }
int main() {
    int a = 10;
    change(&a);
    printf("%d", a);
    return 0;
}

다음 C 코드에서 구조체 포인터의 -> 연산자 사용 결과는?

#include <stdio.h>
struct Point { int x; int y; };
int main() {
    struct Point p = {3, 4};
    struct Point *ptr = &p;
    printf("%d", ptr->x + ptr->y);
    return 0;
}

다음 C 재귀함수(팩토리얼)의 실행 결과는?

#include <stdio.h>
int fact(int n) {
    if (n <= 1) return 1;
    return n * fact(n - 1);
}
int main() {
    printf("%d", fact(5));
    return 0;
}

다음 C 재귀함수(피보나치)의 실행 결과는?

#include <stdio.h>
int fib(int n) {
    if (n <= 1) return n;
    return fib(n - 1) + fib(n - 2);
}
int main() {
    printf("%d", fib(6));
    return 0;
}

다음 C 코드에서 재귀 호출 횟수(fact 함수가 호출되는 총 횟수, 최초 호출 포함)는?

#include <stdio.h>
int fact(int n) {
    if (n <= 1) return 1;
    return n * fact(n - 1);
}
int main() {
    fact(4);
    return 0;
}

다음 C 코드에서 malloc으로 동적 할당한 메모리의 특징으로 옳은 것은?

#include <stdlib.h>
int *p = (int*)malloc(sizeof(int) * 5);

다음 C 코드에서 realloc 사용에 대한 설명으로 옳은 것은?

#include <stdlib.h>
int *p = (int*)malloc(sizeof(int) * 5);
p = (int*)realloc(p, sizeof(int) * 10);

C언어에서 static 지역변수의 특징으로 옳은 것은?

#include <stdio.h>
void counter() {
    static int count = 0;
    count++;
    printf("%d ", count);
}
int main() {
    counter();
    counter();
    counter();
    return 0;
}

다음 C 코드의 printf 형식지정자 사용 결과는?

#include <stdio.h>
int main() {
    float f = 3.14159;
    printf("%.2f", f);
    return 0;
}

다음 C 코드의 실행 결과는? (문자형 출력)

#include <stdio.h>
int main() {
    char c = 'A';
    printf("%c %d", c, c);
    return 0;
}

다음 C 코드에서 #define 매크로의 함정으로 인한 실행 결과는?

#include <stdio.h>
#define SQUARE(x) x * x
int main() {
    int result = SQUARE(2 + 3);
    printf("%d", result);
    return 0;
}

다음 C 코드에서 괄호로 보완된 매크로의 실행 결과는?

#include <stdio.h>
#define SQUARE(x) ((x) * (x))
int main() {
    int result = SQUARE(2 + 3);
    printf("%d", result);
    return 0;
}

다음 C 코드의 실행 결과는? (음수 나머지 연산)

#include <stdio.h>
int main() {
    int a = -7, b = 3;
    printf("%d", a % b);
    return 0;
}

다음 C 코드의 실행 결과는? (register 키워드)

#include <stdio.h>
int main() {
    register int i;
    int sum = 0;
    for (i = 1; i <= 3; i++) sum += i;
    printf("%d", sum);
    return 0;
}

다음 C 코드의 문자 배열 선언과 출력 결과는?

#include <stdio.h>
int main() {
    char str[10] = "NH";
    printf("%s", str);
    return 0;
}

다음 C 코드의 다차원 배열 합계 결과는?

#include <stdio.h>
int main() {
    int arr[2][2] = {{1,2},{3,4}};
    int sum = 0;
    int i, j;
    for (i = 0; i < 2; i++)
        for (j = 0; j < 2; j++)
            sum += arr[i][j];
    printf("%d", sum);
    return 0;
}

다음 C 코드에서 do-while문의 실행 결과는?

#include <stdio.h>
int main() {
    int i = 10;
    do {
        printf("%d ", i);
        i++;
    } while (i < 5);
    return 0;
}

다음 C 코드에서 sizeof 연산자의 결과로 옳은 것은? (int가 4바이트인 환경 기준)

#include <stdio.h>
int main() {
    int arr[10];
    printf("%d", (int)sizeof(arr));
    return 0;
}
